-- INSTRUCTOR ONLY. Do not distribute to trainees.
-- Instructor account (not touched by environment reset) + scenario catalogue.

do $$
declare iid uuid := md5('nuqta-training:user:instructor')::uuid;
begin
  if not exists (select 1 from auth.users where id = iid) then
    insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,
      created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change,email_change_token_current,phone_change,phone_change_token,reauthentication_token)
    values ('00000000-0000-0000-0000-000000000000',iid,'authenticated','authenticated','instructor@training.nuqta-demo.test',
      extensions.crypt('Instructor#2026',extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}','{"full_name":"Training Instructor"}',
      now(),now(),'','','','','','','','');
    insert into auth.identities(id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at)
    values (gen_random_uuid(),iid,iid::text,jsonb_build_object('sub',iid::text,'email','instructor@training.nuqta-demo.test','email_verified',true),'email',now(),now(),now());
    insert into public.profiles(id,email,full_name,title,is_instructor) values (iid,'instructor@training.nuqta-demo.test','Training Instructor','Programme Lead',true);
  end if;
end $$;

insert into public.training_scenarios
(id,title,category,feature,prerequisites,difficulty,severity,expected_secure,flawed_behavior,investigation_path,expected_evidence,business_impact,remediation,chain) values
('S-01','Bootstrap configuration over-disclosure','Information disclosure','App bootstrap / GET /api/v2/meta/config','Any authenticated session','Easy','Low',
 'Bootstrap returns only UI flags needed by the client.','Config also returns the sandbox tenant UUID, a legacy export path and a synthetic signing hint (TRAINING_SECRET_demo_12345).',
 'Observe network calls after login; inspect meta/config response; note tenant id and legacy path.','Response body containing sandboxTenantId and legacyExportPath.',
 'Reveals tenant identifiers and an undocumented endpoint that enables follow-on attacks.','Return only client-required flags; keep tenant identifiers and legacy paths server-side.','CH-A,CH-B'),
('S-02','Document version history without tenant check','IDOR / BOLA','Documents / GET /api/v2/documents/:id/versions','Another org document id','Medium','High',
 'Version history is returned only to members of the owning organization.','Versions endpoint authenticates but does not verify document.org_id against the caller context.',
 'Compare GET /documents/:id (404 cross-tenant) with /documents/:id/versions (200).','Version bodies for a document owned by another organization.',
 'Disclosure of document content across tenants.','Apply the same ownership guard as the parent document route.',NULL),
('S-03','Private AI conversation readable by org peers','Horizontal authorization','Mibyan / GET /api/v2/ai/conversations/:id','Two users in one org','Medium','Medium',
